/**
 * Routes found in the Aisle code that no Dev document lists yet ("code-discovered"). The user approved documenting
 * them (2026-10-29) as **docs-only** entries, labelled "from code — confirm with Dev":
 *
 *   - source record:  m2/docs/code-discovered-routes.json (data) + .md (human-readable), generated by
 *                     `npm run docs:api:drift -- --apply --document-new-routes` from the drift result
 *   - docs:           scripts/api-docs/export.ts adds one entry per route with `docsOnly: true, origin: 'code'`
 *
 * Docs-only means: they are NOT part of the Milestone 2 inventory (m2/scripts/m2-inventory.ts parses only Dev's
 * documents), so they get no QA group, no test case and no test code, and the m2:docs completeness checks (every
 * inventory API has a group and a case) never see them. Only what the code literally shows is recorded: method, path,
 * controller#action with file:line @commit, the literal params read and the literal `render json:` keys. Purpose,
 * auth, caller, personal data, flow and data stores are "not stated".
 */
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import type { CodeSnapshot } from './drift/code';
import type { Finding } from './drift/compare';
import type { ParamType } from './drift/ruby';

export const CODE_ROUTES_JSON = 'm2/docs/code-discovered-routes.json';
export const CODE_ROUTES_MD = 'm2/docs/code-discovered-routes.md';

export interface CodeRoute {
  /** Stable id (CODE-001 …), kept across runs by METHOD + path. */
  id: string;
  method: string;
  path: string;
  /** controller path (v1/payment) and action. */
  controller: string;
  action: string;
  file: string;
  /** Line of the action's `def` (0 when the action is not defined in the controller file). */
  line: number;
  routeLine: number;
  sha: string;
  /** Date the route was first recorded. */
  found: string;
  /** Area key (G1 … G10) — see areaFor(). */
  group: string;
  params: { name: string; required: boolean; type?: ParamType; line: number }[];
  paramsComplete: boolean;
  responseKeys: { name: string; line: number }[];
  responseComplete: boolean;
  /** Why something could not be read statically (verbatim from the reader). */
  notes: string[];
}

export interface CodeRoutesFile {
  about: string;
  routes: CodeRoute[];
}

export const ABOUT_CODE_ROUTES =
  'Routes found in the Aisle code (origin/develop_new) that no Dev API document lists. Docs-only: documented as "from code — confirm with Dev", no QA group or test case. Generated by `npm run docs:api:drift -- --apply --document-new-routes`.';

export function loadCodeRoutes(root: string): CodeRoutesFile {
  const file = path.join(root, CODE_ROUTES_JSON);
  if (!existsSync(file)) return { about: ABOUT_CODE_ROUTES, routes: [] };
  const d = JSON.parse(readFileSync(file, 'utf8')) as Partial<CodeRoutesFile>;
  return { about: d.about ?? ABOUT_CODE_ROUTES, routes: d.routes ?? [] };
}

/**
 * The area of a code-discovered route, from its path only (no behaviour is inferred):
 *   1. a path segment named `*webhook*` or `*callback*` → G9 (provider callbacks);
 *   2. otherwise the area most documented routes share with it under the same first two path segments
 *      (e.g. /V1/payment, /V1/images, /admin/members — /admin/member and /admin/members count as one);
 *   3. otherwise the area of the documented routes served by the same controller; else '' (export: "Other").
 */
export function areaFor(
  route: { method: string; path: string; controller: string },
  documented: { path: string; group: string; controller?: string }[],
): string {
  if (/(webhook|callback)/i.test(route.path.split('/').pop() ?? '')) return 'G9';
  const prefix = (p: string) =>
    p
      .split('/')
      .filter(Boolean)
      .slice(0, 2)
      .join('/')
      .replace(/^admin\/members?$/, 'admin/member');
  const vote = (list: { group: string }[]) => {
    const n = new Map<string, number>();
    for (const d of list) if (d.group) n.set(d.group, (n.get(d.group) ?? 0) + 1);
    return [...n.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]?.[0] ?? '';
  };
  return (
    vote(documented.filter((d) => prefix(d.path) === prefix(route.path))) ||
    vote(documented.filter((d) => d.controller === route.controller))
  );
}

/** Records for the endpoint-added findings (existing ids kept, new ones numbered on). */
export function codeRoutesFrom(
  findings: Finding[],
  head: CodeSnapshot,
  documented: { path: string; group: string; controller?: string }[],
  existing: CodeRoute[],
  today: string,
): CodeRoute[] {
  const out = [...existing];
  let n = Math.max(0, ...existing.map((r) => Number(r.id.replace(/^CODE-/, '')) || 0));
  for (const f of findings.filter((x) => x.kind === 'endpoint-added')) {
    if (out.some((r) => r.method === f.method && r.path === f.path)) continue;
    const e = head.endpoint(f.method, f.path);
    if (!e.route) continue;
    const facts = e.facts;
    n++;
    out.push({
      id: `CODE-${String(n).padStart(3, '0')}`,
      method: f.method,
      path: f.path,
      controller: e.route.controller,
      action: e.route.action,
      file: `app/controllers/${e.route.controller}_controller.rb`,
      line: facts?.line ?? 0,
      routeLine: e.route.line,
      sha: head.sha.slice(0, 7),
      found: today,
      group: areaFor({ method: f.method, path: f.path, controller: e.route.controller }, documented),
      params: (facts?.params ?? []).map((p) => ({
        name: p.name,
        required: p.required,
        ...(p.type ? { type: p.type } : {}),
        line: p.line,
      })),
      paramsComplete: facts?.paramsComplete ?? false,
      responseKeys: facts?.responseKeys ?? [],
      responseComplete: facts?.responseComplete ?? false,
      notes: facts ? facts.review : [e.problem ?? 'action not read'],
    });
  }
  return out;
}

const cell = (s: string) => s.replace(/\|/g, '\\|');

/** The human-readable source record (there is no Dev document for these routes). */
export function codeRoutesMarkdown(file: CodeRoutesFile, areaName: (key: string) => string): string {
  const out = [
    '<!-- GENERATED from m2/docs/code-discovered-routes.json by `npm run docs:api:drift -- --apply --document-new-routes` — do not edit by hand. -->',
    '',
    '# Code-discovered routes (no Dev document)',
    '',
    'Routes found in the Aisle code (`origin/develop_new`, read-only) that are not in any Dev API document. They are documented **docs-only**, labelled **from code — confirm with Dev**: no QA group, no test case. Only what the code literally shows is recorded; purpose, auth, caller, personal data, flow and data stores are not stated.',
    '',
    `${file.routes.length} routes.`,
    '',
    '| ID | Method | Path | Area | Controller#action | Code |',
    '| --- | --- | --- | --- | --- | --- |',
    ...file.routes.map(
      (r) =>
        `| ${r.id} | ${r.method} | \`${r.path}\` | ${cell(areaName(r.group) || 'not stated')} | \`${r.controller}#${r.action}\` | \`${r.line ? `${r.file}:${r.line}` : r.file} @${r.sha}\`, \`config/routes.rb:${r.routeLine}\` |`,
    ),
    '',
  ];
  for (const r of file.routes) {
    out.push(`## ${r.id} · \`${r.method} ${r.path}\``, '');
    out.push(
      `- Route: \`config/routes.rb:${r.routeLine}\` @${r.sha} → \`${r.controller}#${r.action}\``,
      `- Action: ${r.line ? `\`${r.file}:${r.line}\`` : 'not defined in the controller file (not stated)'}`,
      `- Request params read: ${
        r.params.length
          ? r.params
              .map(
                (p) =>
                  `\`${p.name}\` (${[p.required ? 'required' : 'optional', p.type ?? ''].filter(Boolean).join(', ')}, L${p.line})`,
              )
              .join(', ')
          : 'none read literally'
      }${r.paramsComplete ? '' : ' — not complete (see notes)'}`,
      `- Response keys (literal \`render json:\`): ${
        r.responseKeys.length
          ? r.responseKeys.map((k) => `\`${k.name}\` (L${k.line})`).join(', ')
          : 'not stated'
      }${r.responseKeys.length && !r.responseComplete ? ' — not complete (see notes)' : ''}`,
      `- Area: ${areaName(r.group) || 'not stated'} (assigned from the path, see scripts/api-docs/code-routes.ts)`,
    );
    if (r.notes.length) out.push(`- Notes: ${r.notes.map((x) => `\`${x}\``).join('; ')}`);
    out.push('');
  }
  return out.join('\n');
}
